def buscar(lista, objetivo, ini, fin):
    if ini > fin:
        return -1
    medio = (ini + fin) // 2
    if lista[medio] == objetivo:
        return medio
    if lista[medio] < objetivo:
        return buscar(lista, objetivo, medio + 1, fin)
    return buscar(lista, objetivo, ini, medio - 1)

